def icon(k):return f'<svg class="icon" aria-hidden="true" viewBox="0 0 24 24">{icons[k]}</svg>'
def logo(dark=False,cls='logo'):
 name='silex-business-logo-fundo-escuro-transparente.svg' if dark else 'silex-business-logo-fundo-claro-refinado.svg'
 return f'<img class="{cls}" src="assets/{name}" alt="Silex Business" width="1120" height="455">'
def button(text,ico='',cls='',extra=''):
 return f'<button type="button" class="btn {cls}" data-action {extra}>{icon(ico) if ico else ""}{text}</button>'
def document(name,title,content,body=''):
 return f'''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>{title} — estudo SB-01</title><link rel="icon" href="assets/silex-business-app-icon-refinado.svg"><link rel="stylesheet" href="estudos.css"><script src="estudos.js" defer></script></head><body class="{body}"><a class="skip" href="#conteudo">Pular para o conteúdo</a><div class="study-bar"><span>SB-01 · PROTÓTIPO ESTÁTICO · DADOS FICTÍCIOS</span><a href="index.html">Ver os 4 estudos →</a></div>{content}<div class="toast" role="status" hidden></div></body></html>'''
def feature(ico,title,text,action=''):
 return f'<article class="panel feature-card"><div class="feature-icon">{icon(ico)}</div><h3>{title}</h3><p>{text}</p>{f"<button class='text-action' type='button' data-action>{action}{icon('arrow')}</button>" if action else ""}</article>'
def mini():
 return f'''<div class="mini-app"><div class="mini-head">{logo(True)}<span style="font-size:11px">Empresa Exemplo</span></div><div class="mini-body"><h3 class="mini-title">Gestão em perspectiva</h3><small>Demonstração fictícia · outubro de 2026</small><div class="mini-stats"><div class="mini-stat"><small>+ Entradas</small><strong class="income">R$ 12.450,00</strong></div><div class="mini-stat"><small>− Saídas</small><strong class="expense">R$ 7.830,00</strong></div></div><div class="mini-row"><span>Venda ilustrativa<small>Recebimento registrado</small></span><strong class="income">+ R$ 4.800,00</strong></div><div class="mini-row"><span>Frete ilustrativo<small>Pagamento registrado</small></span><strong class="expense">− R$ 2.130,00</strong></div><p class="mini-caption">Valores e registros de exemplo, sem dados de clientes.</p></div></div>'''
