 rows=[('103','Cliente Horizonte','13/10/2026','Pix','480,00','Finalizada'),('102','Cliente Aurora','12/10/2026','Dinheiro','265,00','Finalizada'),('101','Cliente Modelo','11/10/2026','—','120,00','Rascunho')]
 body=''.join(f'<tr><td><strong>#{code}</strong><small>{client}</small></td><td>{date}<small>{payment}</small></td><td class="numeric">R$ {total}</td><td><span class="sale-status {"finalized" if status=="Finalizada" else "draft"}">{status}</span></td><td><button type="button" class="mini-detail" data-action aria-label="Ver venda fictícia {code}">{icon("eye")}</button></td></tr>' for code,client,date,payment,total,status in rows)
