def navitem(name,ico,target='',active=False):
 c=f'nav-link {"active" if active else ""}'
 current=' aria-current="page"' if active else ''
 return f'<a class="{c}" href="{target}"{current}>{icon(ico)}{name}</a>' if target else f'<button class="{c}" type="button" data-action>{icon(ico)}{name}</button>'
def shell(page,content):
 ledger=page=='Lançamentos (Despesa/Receita)'
 nav=navitem('Página inicial','home','c-inicial.html',not ledger)+navitem('Visão Geral','grid')
 groups=[('Cadastros',[('Clientes','users'),('Produtos ou Serviços','box'),('Fornecedores','users'),('Diaristas','users'),('Frete Subcontratado','work')]),('Movimentações',[('Frente de Caixa','cart'),('Vendas','receipt'),('Serviços e pedidos','work'),('Controle de caixa','bank'),('Estoque','box')]),('Financeiro',[('Dashboard','chart'),('Lançamentos (Despesa/Receita)','wallet'),('Conciliação Bancária','bank'),('Contas a Pagar','down'),('Contas a Receber','up'),('Cadastro de Contas','bank'),('Categorias','list'),('SubCategorias','list'),('Relatórios Financeiros','chart')]),('Administração',[('Usuários','users'),('Histórico de operações','clock'),('Empresa e identidade','settings')])]
 for group,items in groups:
  nav+=f'<details class="nav-group" {"open" if (ledger and group=="Financeiro") else ""}><summary class="nav-label">{group}</summary>'
  for title,ico in items:
   nav+=navitem(title,ico,'d-lancamentos.html' if title=='Lançamentos (Despesa/Receita)' else '',ledger and title=='Lançamentos (Despesa/Receita)')
  nav+='</details>'
 return f'''<div class="app-layout"><button class="backdrop" aria-label="Fechar menu"></button><aside class="sidebar" id="menu-lateral" aria-label="Menu do estudo"><button class="drawer-close" aria-label="Fechar menu">{icon('x')}</button><div class="sidebar-brand">{logo(True)}</div><div class="workspace"><span class="avatar">E</span><div><strong>Empresa Exemplo</strong><small>Empresa fictícia · ilustrativo</small></div></div><nav class="side-nav" aria-label="Menu principal">{nav}</nav><div class="sidebar-bottom">Silex Business<br>Gestão empresarial</div></aside><div class="app-main"><header class="topbar"><div class="topbar-left"><button class="mobile-menu" aria-label="Abrir menu" aria-expanded="false" aria-controls="menu-lateral">{icon('menu')}</button><img class="mobile-app-icon" src="assets/silex-business-app-icon-refinado.svg" alt="Silex Business" width="28" height="28"><div class="breadcrumb"><span>Silex Business</span><span>›</span><strong>{'Lançamentos' if ledger else page}</strong></div></div><div class="user"><span class="avatar">A</span><div class="user-text"><strong>Usuário Exemplo</strong><small>Administrador · fictício</small></div><button type="button" aria-label="Sair (ação ilustrativa)" data-action>{icon('logout')}</button></div></header><main class="content" id="conteudo">{content}</main><footer class="app-footer"><span>Silex Business · Empresa Exemplo · dados ilustrativos</span><span>Horário de Manaus · Valores em reais</span></footer></div></div>'''
