for title,ico in [('Frente de Caixa','cart'),('Vendas','receipt'),('Clientes','users'),('Produtos / Serviços','box'),('Lançamentos','wallet'),('Contas a Pagar','down'),('Contas a Receber','up'),('Serviços e pedidos','work')]:
 shortcuts+=f'<a class="shortcut" href="d-lancamentos.html">{icon(ico)}{title}</a>' if title=='Lançamentos' else f'<button class="shortcut" type="button" data-action>{icon(ico)}{title}</button>'
inicial=f'''<div class="page-heading"><div><h1>Página inicial</h1><p>Olá, Usuário Exemplo. Acesse os módulos da sua empresa.</p></div><span class="pill">{icon('clock')}13 de outubro de 2026</span></div><section class="panel company-banner"><div><span class="eyebrow">Empresa ativa · identificação ilustrativa</span><h2>Empresa Exemplo Ltda.</h2><p class="muted">Comércio e serviços · dados fictícios para apresentação</p><div class="company-data"><span>{icon('pin')}Cidade Exemplo / UF</span><span>{icon('mail')}contato@empresa.example</span></div><div class="company-data"><span>Documento e telefone: não informados neste estudo.</span></div></div><img class="hero-symbol" src="assets/silex-business-simbolo-refinado.svg" alt="" width="445" height="455"></section><div class="section-heading"><div><h2>Acesso rápido</h2><p>Exemplo da navegação para o perfil Administrador.</p></div></div><div class="shortcut-grid">{shortcuts}</div><div class="section-heading"><div><h2>Seu ambiente de gestão</h2><p>Encontre a informação certa em cada módulo.</p></div></div><div class="card-grid">{feature('users','Cadastros e catálogo','Clientes, fornecedores, produtos e serviços. Diaristas e frete subcontratado em cadastros próprios.','Ver cadastros')}{feature('work','Serviços e pedidos','Consulte pedidos e seus custos previstos, com vínculo aos títulos financeiros existentes.','Acessar pedidos')}{feature('wallet','Gestão financeira','Consulte lançamentos, pagar e receber. Conciliação por OFX com confirmação manual.','Acessar financeiro')}</div><section class="overview-link"><div><h3>Os indicadores continuam na Visão Geral.</h3><p>Vendas recentes, alertas de estoque e consultas operacionais em uma tela independente.</p></div>{button('Abrir Visão Geral','arrow','light')}</section>'''
save('c-inicial.html', document('C','Inicial autenticada · Silex Business',shell('Página inicial',inicial)))
def field(name,key,options=None,value='',placeholder='',typ='text'):
 if options:
  ctrl=f'<select id="{key}">'+''.join(f'<option>{escape(x)}</option>' for x in options)+'</select>'
 elif typ=='date':
  display='/'.join(reversed(value.split('-')))
  ctrl=f'<span class="date-control"><input id="{key}" type="text" value="{display}" data-iso="{value}" readonly inputmode="numeric" aria-describedby="date-presentation-note"><button class="date-picker" type="button" data-action aria-label="Calendário de {name} (ilustrativo)">{icon("calendar")}</button></span>'
 else:ctrl=f'<input id="{key}" type="{typ}" value="{value}" placeholder="{placeholder}">'
 return f'<label class="field" for="{key}">{name}{ctrl}</label>'
rows=[('13/10/2026','Venda ilustrativa 004','DOC-EX-004','Conta de exemplo','Vendas / Serviços','Venda','income','4.800,00',False),('12/10/2026','Recebimento ilustrativo 003','DOC-EX-003','Conta de exemplo','Vendas / Produtos','Quitação de título','income','7.650,00',False),('10/10/2026','Frete ilustrativo 002','DOC-EX-002 · Prestador Exemplo','Conta de exemplo','Operação / Frete','Manual','expense','2.130,00',True),('08/10/2026','Diárias ilustrativas 001','DOC-EX-001 · Diarista Exemplo','Conta de exemplo','Operação / Diárias','Manual','expense','1.200,00',True),('05/10/2026','Compra ilustrativa 005','DOC-EX-005','Conta de exemplo','Operação / Materiais','OFX','expense','4.500,00',False)]
tbody=''
for date,title,doc,account,cat,origin,direction,val,can_reverse in rows:
 tbody+=f'<tr><td>{date}<small>{date}</small></td><td><strong>{title}</strong><small>{doc}</small></td><td>{account}<small>{cat}</small></td><td>{origin}</td><td class="numeric {direction}">{"+" if direction=="income" else "−"} R$ {val}<small>{"Entrada" if direction=="income" else "Saída"}</small></td><td>{button("Estornar",cls="danger") if can_reverse else "<span class=muted>—</span>"}</td></tr>'
summary=''
for name,ico,val,cls,note in [('Entradas','up','R$ 12.450,00','income','+ Receitas efetivas no período'),('Saídas','down','R$ 7.830,00','expense','− Despesas efetivas no período'),('Saldo do período','scale','R$ 4.620,00','','Entradas menos saídas'),('Lançamentos','list','5','','01/10/2026 a 31/10/2026')]:
 summary+=f'<article class="panel summary-card"><div class="summary-label"><span>{name}</span>{icon(ico)}</div><strong class="{cls}">{val}</strong><small>{note}</small></article>'
filters=field('Busca','busca',['Histórico','Documento'])+field('Pesquisar histórico ou documento','pesquisa',placeholder='Digite e tecle Enter…')+field('Tipo','tipo',['Todas','Receita','Despesa'])+field('Conta','conta',['Todas','Conta de exemplo'])+field('Origem','origem',['Todas','Manual','Quitação de título','Venda','OFX','Estorno'])+field('Comprovante','comprovante',['Todos','Sem comprovante','Com comprovante'])+'<fieldset class="date-basis"><legend>Período por</legend><label><input type="radio" name="base" checked>Lançamento</label><label><input type="radio" name="base">Competência</label></fieldset>'+field('De','de',value='2026-10-01',typ='date')+field('Até','ate',value='2026-10-31',typ='date')+'<button class="btn primary filter-action" type="button" data-action>'+icon('search')+'Pesquisar</button>'
ledger=f'''<div class="page-heading"><div><h1>Lançamentos (Despesa/Receita)</h1><p>Livro caixa: entradas e saídas efetivas por conta.</p></div><div class="actions">{button('Imprimir','print')}{button('Exportar CSV','download')}{button('Nova despesa','plus')}{button('Nova receita','plus','primary')}</div></div><div class="periods" aria-label="Período">{''.join(f'<button type="button" data-action class="{"active" if p=="Mês" else ""}" aria-pressed="{str(p=="Mês").lower()}">{p}</button>' for p in ['Hoje','Semana','Mês','Mês anterior','Ano','Tudo','Personalizado'])}</div><div class="summary-grid">{summary}</div><p class="account-hint">Saldo atual das contas · inclui saldo inicial e todo o histórico · valores fictícios</p><div class="account-strip"><button type="button" class="account-chip active" data-action>{icon('bank')}<span>TODAS AS CONTAS<strong>R$ 8.620,00</strong></span></button><button type="button" class="account-chip" data-action>{icon('bank')}<span>CONTA DE EXEMPLO<strong>R$ 8.620,00</strong></span></button></div><section class="panel filters" aria-label="Filtros de lançamentos"><div class="filter-grid">{filters}</div><p class="filter-help" id="date-presentation-note">Datas exibidas em dd/mm/aaaa. Neste estudo são ilustrativas e não editáveis; valores ISO preservados. Filtros não consultam dados.</p></section><section class="panel table-panel" aria-label="Lançamentos ilustrativos"><div class="table-heading"><h2>Lançamentos</h2><label class="page-size" for="tamanho">Itens por página<select id="tamanho"><option>20</option><option>50</option><option>100</option></select></label></div><p class="table-scroll-hint" id="ledger-scroll-hint">{icon("arrow")}<span>Role horizontalmente para ver todas as colunas e ações.</span></p><div class="table-scroll" tabindex="0" role="region" aria-describedby="ledger-scroll-hint" aria-label="Tabela de lançamentos; use as setas para rolar quando estiver em foco"><table><thead><tr>{''.join(f'<th scope="col">{n}</th>' for n in ['Data / competência','Histórico / documento','Conta / categoria','Origem','Valor','Ações'])}</tr></thead><tbody>{tbody}</tbody></table></div><div class="table-pagination"><span>5 registros fictícios</span><div><button class="btn" type="button" disabled aria-label="Página anterior">‹</button><span>1 de 1</span><button class="btn" type="button" disabled aria-label="Próxima página">›</button></div></div></section><p class="mini-caption">Todos os registros e valores são ilustrativos. Saldo inicial fictício de R$ 4.000,00; saldo do período de R$ 4.620,00; saldo atual de R$ 8.620,00.</p>'''
save('d-lancamentos.html', document('D','Lançamentos · Silex Business',shell('Lançamentos (Despesa/Receita)',ledger)))
gallery=f'''<main class="gallery" id="conteudo">{logo(False,'gallery-logo')}<span class="eyebrow">Identidade visual e navegação</span><h1>Quatro estudos para a Silex Business</h1><p>Protótipos estáticos do SB-01, preparados com os ativos refinados oficiais. Dados fictícios, sem autenticação, API ou alterações no ERP. Revise composição, densidade e organização em desktop e celular.</p><div class="gallery-grid">'''
for letter,name,file,description in [('A','Página pública comercial','a-publica.html','Proposta institucional, módulos e demonstração fictícia, com chamada para Entrar.'),('B','Login','b-login.html','Composição em duas colunas com marca oficial e tipografia Inter local.'),('C','Página inicial autenticada','c-inicial.html','Empresa ativa e atalhos de exemplo para administrador; Visão Geral independente.'),('D','Lançamentos Despesa/Receita','d-lancamentos.html','Períodos, indicadores, contas, filtros e tabela densa com semânticas preservadas.')]:
 gallery+=f'<a class="panel gallery-card" href="{file}"><span class="eyebrow">Estudo {letter}</span><h2>{name}</h2><p>{description}</p><span>Abrir estudo →</span></a>'
gallery+='</div><p>Os botões operacionais apenas informam que a ação não está conectada. O menu móvel e os links entre estudos são controles de apresentação. Não informe credenciais reais.</p></main>'
save('index.html', document('Galeria','Galeria · Silex Business',gallery))
print('Geração concluída; arquivos idênticos preservados; nenhum arquivo de produção modificado.')
